def tm_step(active_columns, learn=True):
    prev_active, prev_winners = active_cells, winner_cells
    active_cells, winner_cells = set(), set()

    # ---- Phase 1: activate cells in each active column ----
    for col in active_columns:
        segs = [s for s in active_segments if column_of(s.cell) == col]
        if segs:                                   # column was predicted
            for s in segs:
                active_cells.add(s.cell); winner_cells.add(s.cell)
                if learn:
                    reinforce(s, prev_active)      # +inc to active presyn, -dec to others
                    grow_synapses(s, prev_winners, MAX_NEW - n_active_potential(s))
        else:                                      # unexpected input: BURST
            active_cells |= cells_in(col)
            best = best_matching_segment(col)      # most potential synapses to prev_active
            if best is not None:
                winner = best.cell
            else:
                winner = least_used_cell(col)      # fewest segments, ties random
            winner_cells.add(winner)
            if learn and prev_winners:
                if best is None:
                    best = winner.create_segment()
                reinforce(best, prev_active)
                grow_synapses(best, prev_winners, MAX_NEW - n_active_potential(best))

    # ---- Punish wrong predictions ----
    if learn and PREDICTED_SEGMENT_DECREMENT > 0:
        for s in matching_segments:
            if column_of(s.cell) not in active_columns:
                for syn in s.synapses:
                    if syn.presyn in prev_active:
                        syn.perm -= PREDICTED_SEGMENT_DECREMENT

    # ---- Phase 2: compute predictions for the next step ----
    active_segments, matching_segments = [], []
    for s in all_segments_with_synapses_to(active_cells):
        n_conn = count(syn.presyn in active_cells and syn.perm >= CONNECTED)
        n_pot  = count(syn.presyn in active_cells)
        if n_conn >= ACTIVATION_THRESHOLD: active_segments.append(s)
        if n_pot  >= MIN_THRESHOLD:        matching_segments.append(s)
    predictive_cells = {s.cell for s in active_segments}
    return active_cells, predictive_cells
